    function showClientDetails(c){if(!c)return;openModal('Detalle de persona demo',`<p><strong>${escapeHtml(c.name)}</strong></p><p>Documento: ${escapeHtml(c.document||'—')}<br>Tipo: ${escapeHtml(c.type||'—')}<br>Teléfono: ${escapeHtml(c.phone||'—')}<br>Email: ${escapeHtml(c.email||'—')}<br>Dirección: ${escapeHtml(c.address||'—')}<br>CI: ${escapeHtml(c.ci||'—')}</p><div class="dialog-actions"><button class="btn btn-light" id="personDetailClose">Cerrar</button><button class="btn btn-blue" id="personDetailEdit">Editar</button></div>`);document.querySelector('#personDetailClose').onclick=closeModal;document.querySelector('#personDetailEdit').onclick=()=>showClientForm(c)}
