    function registerAttendance(type){if(!deviceCode){showToast('Primero crea el código del dispositivo.');return}const employeeCode=document.querySelector('#attendanceEmployeeCode').value.trim().toUpperCase();if(!employeeCode){showToast('Ingresa el código del empleado.');document.querySelector('#attendanceEmployeeCode').focus();return}const employee=personnel.find(p=>p.code.toUpperCase()===employeeCode);if(!employee){showToast('Ese código no existe. Usa “Gestionar códigos” para crearlo.');return}const now=new Date(),time=now.toLocaleTimeString('es-BO',{hour12:false}),hour=String(now.getHours()).padStart(2,'0'),minute=String(now.getMinutes()).padStart(2,'0'),onTime=`${hour}:${minute}`<='08:00';attendance.push({employeeCode,employeeName:employee.name,date:localDateValue(),time,type,device:deviceCode});localStorage.setItem('llanque-demo-attendance',JSON.stringify(attendance));document.querySelector('#attendanceEmployeeCode').value='';const feedback=document.querySelector('#attendanceFeedback');feedback.hidden=false;feedback.className=`attendance-feedback ${type==='Entrada'?(onTime?'punctual':'late'):'departure'}`;feedback.textContent=type==='Entrada'?(onTime?`🎉 ¡Llegaste a tiempo, ${employee.name}! Marcaste a las ${time}. Puntualidad nivel leyenda; el reloj te aplaude. 👏`:`☕ ¡Entrada registrada, ${employee.name}, a las ${time}! Hoy el despertador pidió revancha 😄.`):`✅ ¡Salida registrada a las ${time}, ${employee.name}! Jornada guardada. ¡Que descanses! 🌟`;clearTimeout(attendanceFeedbackTimer);attendanceFeedbackTimer=setTimeout(()=>{feedback.hidden=true},10000);showToast(`${type} registrada a las ${time}.`)}
