    function showMovementDetail(m){if(!m)return;openModal('Detalle de movimiento demo',`<p><strong>${escapeHtml(m.id)}</strong> · ${escapeHtml(m.type)} · ${escapeHtml(m.status||'Activo')}</p><p>Fecha: ${escapeHtml(m.date||m.created)}<br>Almacén: ${escapeHtml(m.warehouse||'COCHABAMBA')}${m.destinationWarehouse?`<br>Almacén destino: ${escapeHtml(m.destinationWarehouse)}`:''}<br>Cliente/Proveedor: ${escapeHtml(m.client||'—')}<br>Factura: ${escapeHtml(m.invoiceNumber||'—')}<br>Usuario: ${escapeHtml(m.user||'LLANQUE (DEMO)')}</p><div class="table-wrap"><table style="min-width:400px"><thead><tr><th>Código</th><th>Producto</th><th class="num">Cantidad</th></tr></thead><tbody>${m.items.map(i=>`<tr><td>${escapeHtml(i.code)}</td><td>${escapeHtml(i.name)}</td><td class="num">${i.qty}</td></tr>`).join('')}</tbody></table></div><p>Total: <strong>${escapeHtml(m.total||'—')}</strong></p><div class="hint">Registro ficticio guardado solo en el navegador.</div><div class="dialog-actions no-print"><button class="btn btn-light" id="movementDetailClose">Cerrar</button><button class="btn btn-blue" id="movementDetailPrint">▤ Imprimir</button></div>`);document.querySelector('#movementDetailClose').onclick=closeModal;document.querySelector('#movementDetailPrint').onclick=()=>showMovementPrint(m)}
    function showMovementPrint(m){if(!m)return;openModal('Vista previa de impresión · Demo',`<article class="movement-print-sheet"><header><div><h2>LLANQUE</h2><small>Sistema de inventarios · Comprobante de demostración</small></div><strong>${escapeHtml(m.id)}</strong></header><h3>${escapeHtml(m.type)}</h3><div class="print-meta"><p><b>Fecha</b><br>${escapeHtml(m.date||m.created||'—')}</p><p><b>Almacén</b><br>${escapeHtml(m.warehouse||'COCHABAMBA')}</p><p><b>Destino</b><br>${escapeHtml(m.destinationWarehouse||'—')}</p><p><b>Cliente / proveedor</b><br>${escapeHtml(m.client||'—')}</p><p><b>N° factura</b><br>${escapeHtml(m.invoiceNumber||'—')}</p><p><b>Usuario</b><br>${escapeHtml(m.user||'LLANQUE (DEMO)')}</p><p><b>Estado</b><br>${escapeHtml(m.status||'Activo')}</p></div><table class="print-items"><thead><tr><th>Código</th><th>Producto</th><th class="num">Cantidad</th><th class="num">Precio</th><th class="num">Total</th></tr></thead><tbody>${m.items.map(i=>`<tr><td>${escapeHtml(i.code||'—')}</td><td>${escapeHtml(i.name||'—')}</td><td class="num">${i.qty||0}</td><td class="num">${escapeHtml(i.price??'—')}</td><td class="num">${escapeHtml(i.total??'—')}</td></tr>`).join('')}</tbody></table><div class="print-total"><span>Total</span><strong>${escapeHtml(m.total||'—')}</strong></div><footer>Documento ficticio para demostración local. Sin validez fiscal y no enviado a Xiren.</footer></article><div class="dialog-actions no-print"><button class="btn btn-light" id="movementPrintClose">Cerrar</button><button class="btn btn-blue" id="movementPrintGo">Imprimir</button></div>`);document.querySelector('#movementPrintClose').onclick=closeModal;document.querySelector('#movementPrintGo').onclick=()=>window.print()}
    function renderKardex(){if(!document.querySelector('#kardexProduct').options.length)renderInventory();const code=document.querySelector('#kardexProduct').value||catalog[0]?.[0],p=catalog.find(x=>x[0]===code);if(!p){document.querySelector('#kardexRows').innerHTML='<tr><td colspan="6" class="empty">No hay productos demo.</td></tr>';return}const events=movements.filter(m=>m.items.some(i=>i.code===code)).map(m=>{const item=m.items.find(i=>i.code===code),out=['Salida por Venta','Salida','Transferencia Salida'].includes(m.type)||(m.type==='Ajuste'&&item.direction==='out'),into=['Entrada por Compra','Entrada','Transferencia Entrada','Devolución Venta','Inventario Inicial'].includes(m.type)||(m.type==='Ajuste'&&item.direction==='in');return {m,item,delta:out?-item.qty:into?item.qty:0}}).sort((a,b)=>new Date(a.m.date||a.m.created)-new Date(b.m.date||b.m.created));let balance=Math.max(0,p[3]-events.reduce((s,e)=>s+e.delta,0));const rows=events.map(e=>{balance+=e.delta;return `<tr><td>${escapeHtml(e.m.date||e.m.created)}</td><td>${escapeHtml(e.m.id)}</td><td>${escapeHtml(e.m.type)}</td><td class="num">${e.delta>0?e.item.qty:0}</td><td class="num">${e.delta<0?e.item.qty:0}</td><td class="num">${balance}</td></tr>`});document.querySelector('#kardexRows').innerHTML=(rows.length?rows.join(''):'')+`<tr><td colspan="5"><strong>Saldo actual demo · ${escapeHtml(p[1])}</strong></td><td class="num"><strong>${p[3]}</strong></td></tr>`}
