    document.querySelector('#newCatalogProduct').addEventListener('click',()=>{openModal('Nuevo producto demo',`<div class="grid"><div class="field"><label>Código</label><input id="newProdCode"></div><div class="field wide"><label>Nombre</label><input id="newProdName"></div><div class="field"><label>Precio venta (Bs.)</label><input id="newProdPrice" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Stock inicial</label><input id="newProdStock" type="number" min="0" step="1" value="0"></div></div><div class="dialog-actions"><button class="btn btn-light" id="prodCancel">Cancelar</button><button class="btn btn-green" id="prodSave">Agregar a demo</button></div>`);document.querySelector('#prodCancel').onclick=closeModal;document.querySelector('#prodSave').onclick=()=>{const code=document.querySelector('#newProdCode').value.trim(),name=document.querySelector('#newProdName').value.trim(),price=Number(document.querySelector('#newProdPrice').value),altPrices=[2,3,4].map(n=>Number(document.querySelector(`#newProdPrice${n}`).value)),stock=Math.floor(Number(document.querySelector('#newProdStock').value));if(!code||!name||catalog.some(p=>p[0].toLowerCase()===code.toLowerCase())||price<0||stock<0){showToast('Completa datos válidos con un código único.');return}catalog.push([code,name,price,stock]);persistDemo();closeModal();renderInventory();showToast('Producto agregado al catálogo demo local.')}});
    function fillProductRow(row,p){row.dataset.code=p[0];row.querySelector('.code').value=p[0];row.querySelector('.name').textContent=p[1];row.querySelector('.unit').innerHTML='<option>Unidad</option><option>Caja</option><option>Paquete</option>';row.querySelector('.unit').disabled=false;row.querySelector('.qty').disabled=false;row.querySelector('.qty').value=1;row.querySelector('.unit-price').disabled=false;row.querySelector('.unit-price').value=p[2].toFixed(2);row.querySelector('.line-discount').disabled=false;row.querySelector('.stock').textContent=p[3];calculate()}
