    document.querySelector('#saleForm').addEventListener('input',()=>{if(!document.querySelector('#mixedPayment').hidden)checkPayLines()});
    function collectSale(){return {id:'D-'+Date.now().toString().slice(-7),date:document.querySelector('#date').value,warehouse:document.querySelector('#warehouse').value,client:document.querySelector('#client').value,payment:document.querySelector('#payment').value,paymentForm:document.querySelector('#paymentForm').value,notes:document.querySelector('#notes').value,items:[...tbody.querySelectorAll('tr')].map(tr=>{const p=catalog.find(x=>x[0]===tr.dataset.code);if(!p)return null;const price=Number(tr.querySelector('.unit-price').value)||0,q=Number(tr.querySelector('.qty').value)||0,d=Number(tr.querySelector('.line-discount').value)||0;return {code:p[0],name:p[1],price,qty:q,discount:d,total:Math.max(0,price*q-d)}}).filter(Boolean),subtotal:document.querySelector('#subtotal').textContent,discounts:document.querySelector('#discounts').textContent,extraDiscount:document.querySelector('#extraDiscount').textContent,total:document.querySelector('#total').textContent,created:new Date().toLocaleString('es-BO')}}
    function exportSalesExcel(){if(!histories.length){showToast('Todavía no hay ventas demo para descargar.');return}const rows=histories.flatMap(sale=>sale.items.map(item=>[sale.id,sale.date||'',sale.created||'',sale.warehouse||'',sale.client||'',sale.payment||'',sale.paymentForm||'',item.code,item.name,item.qty,Number(item.price)||0,Number(item.discount)||0,Number(item.total)||0,sale.total||'']));downloadCsv('LLANQUE_ventas_demo.csv',['Documento','Fecha','Fecha de registro','Almacén','Cliente','Método de pago','Forma de pago','Código','Producto','Cantidad','Precio unitario (Bs.)','Descuento (Bs.)','Total producto (Bs.)','Total venta (Bs.)'],rows);showToast('Ventas demo descargadas; abre el archivo CSV con Excel.')}
    function renderHistory(){openModal('Historial de ventas demo',`<div class="tabs"><button class="tab active" type="button">En este navegador</button><button class="tab" type="button" id="clearHistory">Borrar historial demo</button></div><div class="toolbar"><button class="btn btn-light" type="button" id="historyDownloadSales" ${histories.length?'':'disabled'}>Descargar ventas Excel</button></div><div class="history-list">${histories.length?histories.slice().reverse().map(h=>`<div class="history-item"><div><strong>${escapeHtml(h.id)}</strong><br><small>${escapeHtml(h.created)} · ${escapeHtml(h.client||'Sin cliente')}</small></div><strong>${escapeHtml(h.total)}</strong></div>`).join(''):'<div class="empty">Todavía no hay registros de demostración.</div>'}</div>`);document.querySelector('#historyDownloadSales').onclick=exportSalesExcel;const clear=document.querySelector('#clearHistory');clear.onclick=()=>{histories.splice(0);localStorage.setItem('llanque-demo-history','[]');persistDemo();renderHistory();showToast('Historial demo borrado de este navegador.')}}
    document.querySelector('#historyBtn').addEventListener('click',renderHistory);document.querySelector('#downloadSales').addEventListener('click',exportSalesExcel);
    function showReceipt(sale){openModal('Vista previa de comprobante demo',`<div id="receipt" style="max-width:420px;margin:auto;border:1px dashed #9aa;padding:18px"><h2 style="text-align:center;margin:0">LLANQUE · DEMO</h2><p style="text-align:center">Documento ${escapeHtml(sale.id)}<br>${escapeHtml(sale.created)}</p><hr><p>Cliente: ${escapeHtml(sale.client||'Sin cliente')}<br>Almacén: ${escapeHtml(sale.warehouse)}<br>Pago: ${escapeHtml(sale.payment)} · ${escapeHtml(sale.paymentForm)}</p>${sale.items.map(x=>`<p>${escapeHtml(x.name)} × ${x.qty}<span style="float:right">${fmt(x.total)}</span></p>`).join('')}<hr><h3 style="text-align:right">Total: ${escapeHtml(sale.total)}</h3><small>Documento ficticio. Sin validez fiscal. No se transmitió al ERP.</small></div><div class="dialog-actions"><button class="btn btn-light" id="receiptClose">Cerrar</button><button class="btn btn-blue" id="receiptPrint">Imprimir</button></div>`);document.querySelector('#receiptClose').onclick=closeModal;document.querySelector('#receiptPrint').onclick=()=>window.print()}
    document.querySelector('#printBtn').addEventListener('click',()=>showReceipt(collectSale()));
    function resetDemo(){document.querySelector('#saleForm').reset();tbody.innerHTML='';addRow();document.querySelector('#creditFields').classList.remove('on');document.querySelector('#mixedPayment').hidden=true;document.querySelector('#payLines').innerHTML='';calculate()}
    document.querySelector('#newBtn').addEventListener('click',resetDemo);document.querySelector('#clearBtn').addEventListener('click',resetDemo);document.querySelector('#cancel').addEventListener('click',()=>{resetDemo();showToast('Formulario de demostración reiniciado.')});
    document.querySelector('#saleForm').addEventListener('submit',e=>{e.preventDefault();const sale=collectSale();if(!sale.items.length){showToast('Agrega al menos un producto de demostración.');return}if(!sale.client){showToast('Selecciona un cliente demo para continuar.');return}if(document.querySelector('#payment').value==='Mixto'){const amount=[...document.querySelectorAll('#payLines input')].reduce((a,x)=>a+(Number(x.value)||0),0),total=readTotal();if(Math.abs(amount-total)>.009){showToast('Completa la distribución del pago mixto.');return}}if(sale.paymentForm==='Crédito'&&Number(document.querySelector('#downPayment').value)>readTotal()){showToast('El anticipo no puede superar el total.');return}for(const item of sale.items){const p=catalog.find(x=>x[0]===item.code);if(!p||item.qty>p[3]){showToast(`Stock demo insuficiente para ${item.name}. Disponible: ${p?.[3]||0}.`);return}}for(const item of sale.items){const p=catalog.find(x=>x[0]===item.code);p[3]-=item.qty}histories.push(sale);movements.push({id:sale.id,type:'Salida por Venta',date:sale.date,warehouse:sale.warehouse,client:sale.client,items:sale.items.map(i=>({...i,direction:'out'})),total:sale.total,status:'Activo',created:sale.created});persistDemo();renderInventory();renderMovements();renderKardex();showToast('Salida demo guardada localmente y descontada del inventario demo.');showReceipt(sale)});
    document.querySelector('#saleForm').addEventListener('reset',()=>setTimeout(()=>{calculate();document.querySelector('#editClientBtn').disabled=!document.querySelector('#client').value},0));document.querySelector('#discount').addEventListener('change',calculate);addRow();
